// RefundItem defines model for RefundItem.
type RefundItem struct {
	// AmountCents 该行实退金额，**由服务端算完回传，不接受客户端传入**。
	// 未退完时 = `floor(net × 退货件数 / quantity)`，其中
	// `net = item.amount_cents - item.discount_cents`；
	// 退到最后一件时 = `net - 已退金额`（把余数退干净），
	// 保证 `SUM(amount_cents) = net` 恒等。
	// 余数规则与订单优惠分摊一致 —— 否则用户会遇到「我退完了，钱没退全」。
	AmountCents Money   `json:"amount_cents"`
	ImageUrl    *string `json:"image_url,omitempty"`
	OrderItemId int64   `json:"order_item_id"`
	Quantity    int     `json:"quantity"`

	// Title 下单时的商品标题快照
	Title *string `json:"title,omitempty"`
}

// RefundItemInput defines model for RefundItemInput.
